(function () {
  var REQUIRED_TIME = 60000;
  var STORAGE_KEY = 'adsense_active_time';
  var READY_KEY = 'adsense_active_time_ready';

  var accumulated = Number(sessionStorage.getItem(STORAGE_KEY) || 0);
  var activeSince = null;
  var completed = sessionStorage.getItem(READY_KEY) === '1';

  function getActiveTime() {
    if (activeSince !== null) {
      return accumulated + (performance.now() - activeSince);
    }
    return accumulated;
  }

  function saveTime() {
    accumulated = getActiveTime();
    activeSince = null;
    sessionStorage.setItem(STORAGE_KEY, String(accumulated));
  }

  function activate() {
    if (completed || document.visibilityState !== 'visible') {
      return;
    }
    activeSince = performance.now();
    checkTime();
  }

  function checkTime() {
    if (completed) return;
    if (getActiveTime() >= REQUIRED_TIME) {
      saveTime();
      completed = true;
      sessionStorage.setItem(READY_KEY, '1');
      window.dispatchEvent(new CustomEvent('adsenseActiveTimeReady'));
      return;
    }
    if (activeSince !== null) {
      requestAnimationFrame(checkTime);
    }
  }

  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') {
      saveTime();
    } else {
      activate();
    }
  });

  window.addEventListener('pagehide', saveTime);

  if (!completed) {
    activate();
  } else {
    window.dispatchEvent(new CustomEvent('adsenseActiveTimeReady'));
  }
})();
