:root[data-theme='light'] { --border-color: $(border.color); --search-border-color: $(search.border.color); --body-text-color: $(body.text.color); --body-link-color: $(body.link.color); --black: $(body.link.color); --main-color: $(main.color); --header-bg-color: $(header.bg.color); --site-title-color: $(site.title.color); --scrolling-nav-bg-color: $(scrolling.nav.bg.color); --scrolling-site-title-color: $(scrolling.site.title.color); --main-menu-color: $(main.menu.color); --scrolling-menu-color: $(scrolling.menu.color); --headline-color: $(headline.color); --headline-hover-color: $(headline.hover.color); --headline-bg-color-start: $(headline.bg.color.start); --headline-bg-color-end: $(headline.bg.color.end); --title-color: $(title.color); --dropdown-menu-bg: $(dropdown.menu.bg); --dropdown-menu-color: $(dropdown.menu.color); --dropdown-hover-link-color: $(dropdown.hover.link.color); --dropdown-hover-link-bg-color: $(dropdown.hover.link.bg.color); --post-text-color: $(post.text.color); --meta-text-color: $(meta.text.color); --comments-bg-color: $(comments.bg.color); --left-side: $(left.side); --left-side-triangle: $(left.side.triangle); --right-side: $(right.side); --gradient-color: $(gradient.color); --widget-title-color: $(widget.title.color); --left-side-border-color: $(left.side.border.color); --right-side-border-color: $(right.side.border.color); --footer-bg-color: $(footer.bg.color); --footer-widget-title-color: $(footer.widget.title.color); --footer-text-color: $(footer.text.color); --footer-hover-text-color: $(footer.hover.text.color); --credits-divider-color: $(credits.divider.color); --switcher-background: $(switcher.background); --switcher-circle-background: $(switcher.circle.background); --sun-color: $(sun.color); --moon-color: $(moon.color); }
