.badge-primary, .bg-primary { background-color: var(--primary) !important; }
.badge-secondary, .bg-secondary { background-color: var(--secondary) !important; }
.badge-success, .bg-success { background-color: var(--success) !important; }
.badge-info, .bg-info { background-color: var(--info) !important; }
.badge-warning, .bg-warning { background-color: var(--warning) !important; }
.badge-danger, .bg-danger { background-color: var(--danger) !important; }
.badge-light, .bg-light { background-color: var(--light) !important; }
.badge-dark, .bg-dark { background-color: var(--dark) !important; }
.badge-gradient, .bg-gradient { background-image: linear-gradient(90deg,$(primary.color),$(danger.color)); }
.btn-primary:not(:disabled):not(.disabled):active, .btn-primary:not(:disabled):not(.disabled).active, .show > .btn-primary.dropdown-toggle, .btn-primary, .btn-primary:hover { background-color: var(--primary); border-color: var(--primary); }
.btn-secondary:not(:disabled):not(.disabled):active, .btn-secondary:not(:disabled):not(.disabled).active, .btn-secondary, .btn-secondary:hover { background-color: var(--secondary); border-color: var(--secondary); }
.btn-success:not(:disabled):not(.disabled):active, .btn-success:not(:disabled):not(.disabled).active, .btn-success, .btn-success:hover { background-color: var(--success); border-color: var(--success); }
.btn-info:not(:disabled):not(.disabled):active, .btn-info:not(:disabled):not(.disabled).active, .btn-info, .btn-info:hover { background-color: var(--info); border-color: var(--info); }
.btn-warning:not(:disabled):not(.disabled):active, .btn-warning:not(:disabled):not(.disabled).active, .btn-warning, .btn-warning:hover { background-color: var(--warning); border-color: var(--warning); }
.btn-danger:not(:disabled):not(.disabled):active, .btn-danger:not(:disabled):not(.disabled).active, .btn-danger, .btn-danger:hover { background-color: var(--danger); border-color: var(--danger); }
.btn-light:not(:disabled):not(.disabled):active, .btn-light:not(:disabled):not(.disabled).active, .btn-light, .btn-light:hover { background-color: var(--light); border-color: var(--light); }
.btn-dark:not(:disabled):not(.disabled):active, .btn-dark:not(:disabled):not(.disabled).active, .btn-dark, .btn-dark:hover { background-color: var(--dark); border-color: var(--dark); }
.btn-search, .btn-search:hover { background-color: var(--color-4); border-color: var(--color-4); color: var(--white); }
.border { border: $(border.width) solid $(border.color) !important; }
.border-top { border-top: $(border.width) solid $(border.color) !important; }
.border-right { border-right: $(border.width) solid $(border.color) !important; }
.border-bottom { border-bottom: $(border.width) solid $(border.color) !important; }
.border-left { border-left: $(border.width) solid $(border.color) !important; }
::selection { text-decoration: none; background-color: var(--color-4); color: var(--white); }
.text-main { color: var(--main-color); }
/* General ===================================== */ *, *::before, *::after { word-break: break-word; box-sizing: border-box; }
.hidden {display: none;} .container .container {padding: 0;} button:focus, button:active:focus, button.active { outline: none; -webkit-box-shadow: none; box-shadow: none; }
a.badge:focus { outline: 0; box-shadow: none; }
p { margin-bottom: 25px; }
.radius-0 { border-radius: 0; }
.fbt-post-thumbnail, .fbt-item-thumbnail, .fbt-item-thumbnail-single, .post-content img, .radius-10 { border-radius: $(block.radius)!important; overflow: hidden!important; }
.radius-25 { border-radius: 25px!important; overflow: hidden!important; }
.o-visible { overflow: visible!important; }
.list-unstyled li a { padding: .4rem 0; display: block; }
.list-unstyled li:first-child a { padding-top: 0; }
.list-unstyled li:last-child a { padding-bottom: 0; }
.fbt-resize { width: 100%; max-width: 100%; height: 100%; max-height: 100%; position: relative; background-position: center; -webkit-background-size: cover; -moz-background-size: cover; background-size: cover; -o-background-size: cover; }
:focus {outline: 0;}
.divider {position: relative;transition: var(--theme-transition);}
.divider:before { margin-bottom: 1.5rem; display: block; width: 100%; height: 1px; content: ''; background: var(--credits-divider-color); opacity: .6; transition: var(--theme-transition); }
.divider.top:before { margin-bottom: 0; height: $(divider.top.height); }
@media (min-width: 1365.98px) { .container { max-width: $(container.width); }
.canvas-modern .slider-container .FeaturedPostContainer .container { max-width: calc($(container.width) + 30px); } }
#page-wrapper { background-color: $(page.wrapper.bg.color); max-width: $(page.wrapper.width); margin-top: $(container.margin.top); margin-bottom: $(container.margin.bottom); margin-left: auto; margin-right: auto; box-shadow: 0 0 $(page.wrapper.shadow) rgba(23,16,159,.15); position: relative; }
@media (max-width: 1365.98px) { .text-responsive { font-size: calc(150% + 1vw + 1vh)!important; } }
@media (max-width: 991.98px) { .fbt-main-wrapper { margin-bottom: $(widget.margin); }
.home:not(.canvas-modern) .fbt-main-wrapper { margin-bottom: 0; } }
.btn:hover { opacity: .9; }
blockquote { margin: 0 0 25px; }
blockquote .card { background-color: var(--color-1); border-radius: 0; }
[data-theme='dark'] blockquote .card { background-color: var(--dark); }
blockquote p { position: relative; color: var(--black); }
blockquote p:before { content: '\f10d'; color: var(--black); font-size: 3.7em; opacity: .1; font-family: FontAwesome; position: absolute; top: -10px; left: -25px; }
.CSS_LIGHTBOX { z-index: 9999!important; }
.CSS_LAYOUT_COMPONENT.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER { display: none; }
#cookieChoiceInfo { bottom: 0; top:auto; background: var(--white); box-shadow: 0 4px 30px rgba(0,0,0,0.1); }
[data-theme='dark'] #cookieChoiceInfo { background: var(--dark); }
.cookie-choices-info .cookie-choices-text { font-size: 12px!important; color: var(--black)!important; }
.cookie-choices-info .cookie-choices-button { text-transform: capitalize!important; color: var(--white); background: var(--color-4); font-weight: 300!important; padding: .75rem 1.2rem!important; }
.cookie-choices-info .cookie-choices-button a { padding: 0!important; }
@media (min-width: 1200px) { .fbt-sticky-content { top: $(menu.height); } }
@media (max-width: 1199.98px) { .fbt-sticky-content { top: 10px; } }
body { background: $(body.background); color: var(--body-text-color); font: var(--index-text-font); overflow-x: hidden; transition: var(--theme-transition); }
[data-theme="dark"] body { background: var(--body-dark); }
a { color: var(--black); -webkit-transition: color .20s, background .20s, opacity .20s; transition: color .20s, background .20s, opacity .20s; }
a .fa,a .fab,a .fad,a .fal,a .far,a .fas { font-size: calc($(body.text.font.size) + 1px); }
a:hover h1, a:hover h2, a:hover h3, a:hover h4, a:hover h5, a:hover h6, a:hover .h1, a:hover .h2, a:hover .h3, a:hover .h4, a:hover .h5, a:hover .h6, a:hover { color: var(--main-color); text-decoration: none; }
p {line-height: 1.6em;}
/* Bootstrap Buttons ===================================== */ .btn:focus, .btn.focus {box-shadow: none;} .btn:not(:disabled):not(.disabled):active:focus, .btn:not(:disabled):not(.disabled).active:focus {-webkit-box-shadow: none;box-shadow: none;}
/* Typography ===================================== */ h1, h2, h3, h4, h5, h6, h1 a, h2 a, h3 a, h4 a, h5 a, h6 a, .h1, .h2, .h3, .h4, .h5, .h6 {color: var(--title-color);margin: 0;} h1, .h1 {font: var(--h1-font);line-height: 1.25;} h2, .h2 {font: var(--h2-font);line-height: 1.25;} h3, .h3 {font: var(--h3-font);line-height: 1.25;} h4, .h4 {font: var(--h4-font);line-height: 1.25;} h5, .h5 {font: var(--h5-font);line-height: 1.25;} h6, .h6 {font: var(--h6-font);line-height: 1.25!important;}
/* Widget Settings ===================================== */ .canvas-modern .sidebar-wrapper { display: block; }
.sidebar-wrapper .widget, #footer-content .widget { margin: $(widget.margin) 0; line-height: 100%; }
@media (max-width; 991.98px) { .sidebar-wrapper .widget, #footer-content .widget { margin: calc($(widget.margin) - 20px) 0; } }
