#comments .comment .comment-header .datetime { bottom: 0; display: inline-block; font-size: 13px; margin-left: 8px; }
#comments .comment .comment-content, .comment .comment-body { margin-top: 12px; word-break: break-word; }
.comment-body { margin-bottom: 12px; }
#comments.embed[data-num-comments="0"] { border: 0; margin-top: 0; padding-top: 0; }
#comments.embed[data-num-comments="0"] #comment-post-message, #comments.embed[data-num-comments="0"] div.comment-form>p, #comments.embed[data-num-comments="0"] p.comment-footer { display: none; }
#comment-editor-src { display: none; }
#comments .comments-content .loadmore.loaded { max-height: 0; opacity: 0; overflow: hidden; }
#comments a, #comments cite, #comments div { font-size: calc($(body.text.font.size) + 1px); line-height: 1.4; }
#comments .comment .comment-header .user, #comments .comment .comment-header .user a { color: var(--title-color); font: var(--h6-font); }
#comments .comment .comment-header .user { margin-right: 2px; }
#comments .comment .comment-header .datetime a { color: var(--black); font: var(--index-text-font); }
#comments .comment .comment-content { margin-top: 15px; margin-bottom: 15px; background: var(--white); color: var(--post-text-color); padding: 25px 30px; border-radius: 20px; transition: var(--theme-transition); }
[data-theme='dark'] #comments .comment .comment-content { background: var(--dark); }
#comments .continue { display: none; }
#comments p, #comments .comment-footer { margin: 0; }
.comment-actions a { color: var(--color-4); font-size: 12px!important; }
.comment-actions .item-control a { color: var(--color-5); }
.cmt_iframe_holder{ margin-left: 140px!important; }
body.item-view .cmt_iframe_holder{ margin: 32px 24px!important; }
@media (max-width: 991.98px) { .blog-post-comments { padding: 30px; }
.comment .avatar-image-container { position: relative; }
.comment-header { position: absolute; top: 0; left: 50px; display: grid; }
#comments .comment .comment-header .datetime { margin-left: 0; }
.comment .comment-block { margin-left: 0; }
#comments .comment .comment-replybox-single, #comments .comment-thread .comment-replies { margin-left: 30px; } }
/* Footer ===================================== */ #footer-content { position: relative; }
.fbt-footer-block .fbt-sep-title { margin-bottom: 20px; }
.fbt-footer-block .fbt-sep-title h4.title-heading-left { color: var(--footer-widget-title-color); font: var(--footer-widget-title-font); height: auto; line-height: 1.2em; padding: 0; border: 0; background-color: transparent; }
.fbt-footer-block .post-title, .fbt-footer-block a { color: var(--footer-widget-title-color); }
.fbt-footer-block .post-title a:hover { color: var(--footer-hover-text-color); }
.fbt-footer-block .fbt-sep-title h4.title-heading-left:after { border: 0; }
.fbt-footer-block .fbt-sep-title .title-sep-container, .fbt-footer-block .fbt-sep-title .title-sep.sep-double { height: auto; }
.fbt-footer-block .fbt-sep-title .title-sep { border: 0; background-color: transparent; background-image: none; }
.fbt-footer-block { background-color: var(--footer-bg-color); color: var(--footer-text-color); margin-top: $(footer.margin.top); transition: var(--theme-transition); }
@media (max-width: 991.98px) { .fbt-footer-block { margin-top: calc($(footer.margin.top) - 20px); } }
.fbt-footer-block .divider.top { padding-bottom: $(footer.padding.top)!important; }
.fbt-footer-block .container.pb-4 { padding-bottom: $(footer.padding.bottom)!important; }
.fbt-footer-block p { color: var(--footer-text-color); line-height: 1.65; margin-bottom: 0; }
.fbt-footer-block .nav-link { color: var(--footer-text-color); }
.fbt-footer-block .nav-link:hover { color: var(--footer-hover-text-color); }
.fbt-footer-block .list-unstyled { margin-bottom: 0; }
.fbt-footer-block .list-unstyled li a { color: var(--footer-text-color); }
.fbt-footer-block .list-unstyled li a:hover { color: var(--footer-hover-text-color); text-decoration: none; }
#footer-right-big .widget { margin-bottom: 3rem!important; }
#footer-right-big .widget p { margin-bottom: 25px; }
[data-theme='dark'] .footer-1 #Image2 img { -webkit-filter: brightness(0) invert(1); filter: brightness(0) invert(1); }
/* Popular Posts ===================================== */ .PopularPosts .fbt-title-caption .post-title { font: var(--h6-font); margin-bottom: 0; }
.PopularPosts article { padding: $(pp.post.padding) 0; margin-bottom: $(pp.post.margin); }
.PopularPosts .border-top { border-width: 0!important; }
.PopularPosts article:first-child { padding-top: $(pp.post.fch.lch.padding); }
.PopularPosts article:last-child { margin-bottom: 0!important; }
.PopularPosts .post-meta { margin-top: 7px; display: block; }
.PopularPosts .pp-post-tag { margin-bottom: 5px; display: inline-block; font-size: 12px; }
/* Label Cloud ===================================== */ .fbt-label-cloud { color: #fff; background: var(--main-color); padding: 4px 7px 4px; margin-bottom: 3px; display: inline-block; border-radius: 3px; }
/* Blogger Widgets ===================================== */ .sidebar .widget .card:before { position: absolute; content: ''; width: 100%; height: 1.5px; background: #fff; top: -1px; left: 0; }
/* Archive */ #ArchiveList select {background: var(--light);border:2px solid #eee;cursor:pointer;padding:10px;width:100%;font-size: 14px;} .BlogArchive #ArchiveList ul ul li {padding-left:1.2em;} /* Profile */ .widget.Profile{border-top:0;margin:0;margin-left:38px;margin-top:24px;padding-right:0 }body.sidebar-visible .widget.Profile{margin-left:0 }.widget.Profile .individual{text-align:center }.widget.Profile .individual .default-avatar-wrapper .avatar-icon{margin:auto }.widget.Profile .team{margin-bottom:32px;margin-left:32px;margin-right:32px }.widget.Profile ul{list-style:none;padding:0 }.widget.Profile li{margin:10px 0;text-align:left }.widget.Profile .profile-img{border-radius:50%;float:none }.widget.Profile .profile-info{margin-bottom:12px }.profile-snippet-fade{background:-webkit-linear-gradient(right,#ffffff 0,#ffffff 20%,rgba(255, 255, 255, 0) 100%);background:linear-gradient(to left,#ffffff 0,#ffffff 20%,rgba(255, 255, 255, 0) 100%);height:1.7em;position:absolute;right:16px;top:11.7em;width:96px }.profile-snippet-fade::after{content:'\2026';float:right }.widget.Profile .profile-location{color:#000000;font-size:16px;margin:0;opacity:.74 }.widget.Profile .team-member .profile-link::after{clear:both;content:'';display:table }.widget.Profile .team-member .profile-name{word-break:break-word }.widget.Profile .profile-datablock .profile-link{color:var(--dark);font:var(--h5-font);font-size:24px;text-transform:none;word-break:break-word }.widget.Profile .profile-datablock .profile-link+div{margin-top:16px!important }.widget.Profile .profile-link{font:var(--h6-font);font-size:14px }.widget.Profile .profile-textblock{color:var(--dark);font-size:14px;line-height:24px;margin:0 18px;opacity:.74;overflow:hidden;position:relative;word-break:break-word;}
/* Wikipedia */ .sidebar-wrapper .wikipedia-search-results, .wikipedia-search-results-header {margin-bottom: .5rem;}#wikipedia-search-result-link {padding: 5px 0;}.sidebar-wrapper .wikipedia-search-results a { margin-left: 15px;}
/* Translate */ .goog-te-combo {width: 100%;padding: 10px;}
/* Attribution */ .svg-icon-24, .svg-icon-24-button {cursor: pointer;height: 16px;width: 16px;min-width: 16px;} .Attribution{text-align:center} .Attribution .blogger img,.Attribution .blogger svg{vertical-align:bottom;} .Attribution .blogger img{margin-right:.5em;} .Attribution div{line-height:16px;margin-top:.5em;} .Attribution .copyright,.Attribution .image-attribution{margin-top:.5em;} .sidebar-wrapper .Attribution a {}
/* PageList */ .PageList .nav-link {padding: .5rem .5rem;} .footer-menu .PageList .nav-link {padding: 0 .75rem;} .footer-menu .PageList .nav-item:last-child .nav-link {padding-right: 0;} .footer-menu .PageList .nav-item:first-child .nav-link {padding-left: 0;} .footer-menu .PageList ul {-ms-flex-pack: center !important;justify-content: center !important;margin-top: 1rem !important;}
@media (min-width: 992px) { .footer-menu .PageList ul {-ms-flex-pack: end !important;justify-content: flex-end !important;margin-top: 0 !important;} }
.sidebar-wrapper .LinkList ul.list-unstyled { margin-bottom: 0; }
.sidebar-wrapper .LinkList li { font-weight: bold; }
.sidebar-wrapper .LinkList .fa { font-size: 17px; width: 40px; height: 40px; line-height: 40px; border: 1px solid var(--border-color); border-radius: 2000px; text-align: center; margin-right: 10px; }
/* Forms */ .BlogSearch form { position: relative; overflow: hidden; }
.BlogSearch .form-control { width: 100%!important; height: calc(1.5em + 0.75rem + 6px); font-size: $(body.text.font.size); }
.BlogSearch form .btn { position: absolute; right: 0; top: 0; }
/* Ads */ .fbt-ad-title { font-size: 10.2px; text-transform: uppercase; letter-spacing: .15em; color: var(--black); position: relative; width: 100%; display: inline-block; }
.ContactForm .contact-form-button { background: var(--color-4); color: $(white.color); border: 0!important; border-radius: var(--block-radius)!important; overflow: hidden!important; padding-left: 1.75rem!important; padding-right: 1.75rem!important; padding-bottom: .5rem!important; padding-top: .5rem!important; min-width: 200px; }
.ContactForm .contact-form-button:hover { background: var(--color-5); color: $(white.color); }
.form-control { border-color: var(--border-color); transition: var(--theme-transition); }
[data-theme='dark'] .form-control { background-color: rgba(255,255,255,0.1); color: var(--white); }
[data-theme='dark'] .form-control::placeholder { color: var(--white); }
/* Nav Search ===================================== */ .nav__search-box { width: 300px; position: absolute; right: 15px; top: 100%; padding: 15px 20px; display: none; -webkit-box-shadow: 0 10px 30px rgba(0, 0, 0, 0.09); box-shadow: 0 10px 30px rgba(0, 0, 0, 0.09); background: var(--dropdown-menu-bg); z-index: 1030; }
@media only screen and (max-width: 991.98px) { .nav__search-box { top: calc(100% + .5rem); } }
@media only screen and (max-width: 991.98px) { .nav__search-box { width: 100%; right: 0; } }
/* Homepage top Popular Posts ===================================== */ .fbt-item-thumbnail { overflow: hidden; }
.top-pp-posts { display: -ms-grid; display: grid; grid-template-columns: repeat(5, 1fr); grid-gap: var(--grid-gap); }
@media(min-width: 992px) { .canvas.grid-4.pp-bg #PopularPosts1 .top-pp-posts { background-image: linear-gradient(180deg, transparent, var(--white) 80%),radial-gradient(ellipse at top left, var(--color-3), transparent 50%),radial-gradient(ellipse at top right, var(--info), transparent 50%),radial-gradient(ellipse at center right, var(--warning), transparent 50%),radial-gradient(ellipse at center left, var(--primary), transparent 50%); padding: var(--grid-gap) var(--grid-gap) 0; border-radius: calc(var(--block-radius) + 10px) calc(var(--block-radius) + 10px) 0 0; transition: var(--theme-transition); }
[data-theme='dark'] .canvas.grid-4.pp-bg #PopularPosts1 .top-pp-posts { background-image: none; padding: 0; border-radius: 0; } }
@media (min-width: 1200px) { .single-pp-post-wrapper .top-pp-posts { grid-template-columns: repeat(5, 1fr); } }
@media (max-width: 1199.98px) { .top-pp-posts, .single-pp-post-wrapper .top-pp-posts { grid-template-columns: repeat(4, 1fr); } .top-pp-posts .post:last-child, .single-pp-post-wrapper .top-pp-posts .post:last-child { display: none; } }
@media (max-width: 991.98px) { .single-pp-post-wrapper .top-pp-posts, .top-pp-posts { -ms-grid-columns: 1fr; grid-template-columns: 1fr; grid-row-gap: 40px; } }
.top-pp-posts article { margin: 0; counter-increment: fbt-counter; }
.top-pp-posts article .fbt-item-thumbnail { position: relative; padding-top: 65%; }
.canvas .top-pp-posts article:nth-child(odd) .fbt-item-thumbnail { position: relative; padding-top: 100%; }
@media (max-width: 991.98px) { .canvas .top-pp-posts article:nth-child(odd) .fbt-item-thumbnail { padding-top: 65%; } }
.canvas .top-pp-posts article:nth-child(even) .fbt-item-thumbnail { position: relative; padding-top: 65%; }
@media(min-width: 992px) { .canvas.grid-4 .top-pp-posts article:nth-child(even) .fbt-item-thumbnail { padding-top:100%; } }
@media (max-width: 991.98px) { .canvas .top-pp-posts article:nth-child(even) .fbt-item-thumbnail { padding-top: 65%; } }
.top-pp-posts article .fbt-item-thumbnail .post-thumbnail { position: absolute; top: 0; left: 0; }
.top-pp-posts .is-content { display: -webkit-box; display: -ms-flexbox; display: flex; -webkit-box-orient: horizontal; -webkit-box-direction: normal; -ms-flex-flow: row nowrap; flex-flow: row nowrap; -webkit-box-align: center; -ms-flex-align: center; align-items: center; margin-top: 20px; position: relative; }
.top-pp-posts .is-content::before { -ms-flex-negative: 0; flex-shrink: 0; content: counter(fbt-counter); display: -webkit-inline-box; display: -ms-inline-flexbox; display: inline-flex; -webkit-box-pack: center; -ms-flex-pack: center; justify-content: center; -webkit-box-align: center; -ms-flex-align: center; align-items: center; width: 32px; height: 32px; line-height: 1; border-radius: 1000px; font-size: 14px; background: var(--color-3); color: var(--white); font-weight: bold; }
.single-pp-post-wrapper .top-pp-posts .is-content::before { display: none; }
.top-pp-posts .fbt-title-caption { display: -ms-grid; display: grid; grid-gap: 13px; margin-left: 20px; }
.top-pp-posts .fbt-title-caption .entry-title .fbt-post-title { display: inline; margin-right: .1rem; }
.top-pp-posts .fbt-title-caption .post-excerpt { font-weight: 300; opacity: .8; display: inline; }
.top-pp-posts .post-meta { margin: 0; }
.top-pp-posts .post-meta .label-link { display: none; }
.top-pp-posts .post-meta .label-link:first-child { display: block; color: var(--color-3); text-transform: uppercase; }
.is-bordered { padding: var(--grid-gap); background: var(--color-5); }
@media (max-width: 1199.98px) { .is-bordered { padding: 30px; } }
.top-pp-posts.is-bordered a .entry-title, .top-pp-posts.is-bordered a .h5 { color: var(--white); }
.top-pp-posts.is-bordered a:hover .entry-title, .top-pp-posts.is-bordered a:hover .h5 { color: var(--color-3); }
/* Featured Post ===================================== */ .FeaturedPost .is-fp-container { display: -ms-grid; display: grid; -ms-grid-columns: 1fr 1.54fr; grid-template-columns: 1fr 1.54fr; grid-column-gap: var(--grid-gap); grid-row-gap: calc(var(--grid-gap) - 20px); }
@media (min-width: 992px) { .canvas.grid-4.pp-bg .FeaturedPost .is-fp-container { -ms-grid-columns: 1fr 1.5fr; grid-template-columns: 1fr 1.5fr; } }
@media (max-width: 991.98px) { .FeaturedPost .is-fp-container { -ms-grid-columns: 1fr; grid-template-columns: 1fr; } }
.FeaturedPost .is-fp-container .is-fp-content { display: -ms-grid; display: grid; -ms-flex-line-pack: center; align-content: center; }
.FeaturedPost .fbt-post-thumbnail { padding-top: 62%; }
.FeaturedPost .fbt-fp-content .post-title { font-size: 2.2rem; display: inline; margin-right: 0.1rem; }
@media(max-width: 1199.98px) { .FeaturedPost .fbt-fp-content .post-title { font-size: 1.8rem; } }
@media(max-width: 767.98px) { .FeaturedPost .fbt-fp-content .post-title { font-size: 22px; } }
.FeaturedPost .fbt-fp-content .post-excerpt { display: inline; font-weight: 300; opacity: .8; }
.FeaturedPost .post-meta { margin: 0; }
.FeaturedPost .post-meta .label-link { display: none; }
.FeaturedPost .post-meta .label-link:first-child { display: block; color: var(--color-3); text-transform: uppercase; font-size: 15px; }
/* Header Ads ===================================== */ .fbt-top-header-ad { position: relative; padding-top: 0; -webkit-transition: all .6s; transition: all .6s; z-index: 1; }
.fbt-top-header-ad .ad-image-iframe { clip: rect(0, auto, auto, 0); overflow: hidden; position: absolute; left: 0; top: 0; width: 100%; height: 100%; }
.fbt-top-header-ad .img-iframe { position: fixed; text-align: center; width: 100%; top: 0; left: 0; }
.fbt-top-header-ad .img-iframe img { max-width: 100%; height: auto; }
/* Dark Mode Switcher ===================================== */ .header-right { display: flex; align-items: center; }
.dark-mode-switcher { margin-left: $(switcher.margin.left); }
@media (max-width: 991.98px) { .dark-mode-switcher { margin-left: 0; } }
.dark-mode-switcher.no-items { margin-left: 0; }
#theme-switcher { background-color: var(--switcher-background); border-radius: 50px; display: flex; align-items: center; gap: .5rem; cursor: pointer; padding: .3rem; position: relative; transition: var(--theme-transition); }
#theme-switcher::before { content: ''; position: absolute; width: 1.4rem; height: 1.4rem; background-color: var(--switcher-circle-background); border-radius: 50px; z-index: 0; left: .12rem; top: 50%; transform: translateY(-50%); transition: var(--theme-transition); }
[data-theme='dark'] #theme-switcher::before { left: auto; right: .12rem; }
#theme-switcher svg { z-index: 1; width: 16px; height: 16px; transition: var(--theme-transition); }
#icon-sun { fill: var(--sun-color); stroke: var(--sun-color); }
#icon-moon { fill: var(--moon-color); stroke: var(--moon-color); }
/* Modern Style ===================================== */ @media (min-width: 1200px) { .canvas-modern .fbt-main-wrapper { flex: 0 0 70%; max-width: 70%; }
.canvas-modern .sidebar-wrapper { flex: 0 0 30%; max-width: 30%; } }
@media (min-width: 992px) { .canvas-modern .fbt-main-wrapper { flex: 0 0 66.666667%; max-width: 66.666667%; }
.canvas-modern .sidebar-wrapper { flex: 0 0 33.333333%; max-width: 33.333333%; } }
