@media (max-width: 991.98px) { .canvas-modern header { margin-bottom: calc(var(--header-margin) - 20px)!important; } }
.canvas-modern .fbt-index-post-wrap { grid-template-columns: 1fr; grid-row-gap: var(--grid-gap); }
