@media (max-width: 1199.98px) and (min-width: 768px) { .canvas-modern .bp-content { -ms-grid-columns: 30% auto; grid-template-columns: 30% auto; } }
@media (max-width: 767.98px) and (min-width: 576px) { .canvas-modern .bp-content { -ms-grid-columns: 40% auto; grid-template-columns: 40% auto; grid-column-gap: calc(var(--grid-gap) - 10px); } }
