.canvas-modern .dropdown .dropdown-menu:before, .canvas-modern .blog-wtitle { display: none; }
@media (min-width: 992px) { .canvas-modern .dropdown .dropdown-menu { border: 1px solid var(--border-color); border-radius: var(--block-radius); padding: 1rem 0; } .canvas-modern .dropdown .dropdown-menu .dropdown-item { position: relative; padding: 0.49rem 1.4rem 0.47rem calc(1.4rem - 3px); } }
@media (min-width: 992px) { .canvas-modern .nav__search-box { border: 1px solid var(--border-color); border-radius: var(--block-radius); } }
