/* RTL ===================================== */ html[dir='rtl'] { direction: rtl; unicode-bidi: embed; -webkit-locale: RTL; text-align: right; }
[dir='rtl'] div {direction:rtl;} [dir='rtl'] p, [dir='rtl'] ul, [dir='rtl'] ol, [dir='rtl'] dl {text-align: right!important;}
[dir='rtl'] .fbt-right-headline li:first-child a, [dir='rtl'] .fbt-right-headline li:first-child .nav-link { padding-left:0.75rem!important; padding-right: 0!important; }
[dir='rtl'] .fbt-right-headline li:last-child a, [dir='rtl'] .fbt-right-headline li:last-child .nav-link { padding-right: 0.75rem!important; padding-left: 0!important; }
[dir='rtl'] .fbt-left-headline li:not(:first-child) a:before, [dir='rtl'] .fbt-left-headline li:not(:first-child) .nav-link:before { margin: 0 0 3px 0.6rem; }
