/* Breadcrumbs UI - Estilo Premium */ .fbt-breadcrumbs { margin-bottom: 20px; background: transparent; padding: 0; } .fbt-breadcrumbs .breadcrumb { background: transparent; padding: 0; margin: 0; font-size: 0.85rem; font-weight: 500; } .fbt-breadcrumbs .breadcrumb-item + .breadcrumb-item::before { content: "\f105"; /* FontAwesome Angle Right */ font-family: 'FontAwesome'; color: #adb5bd; } .fbt-breadcrumbs a { color: var(--main.color, #47c3fb); text-decoration: none; transition: color 0.2s; } .fbt-breadcrumbs a:hover { color: var(--primary.color, #007bff); } .fbt-breadcrumbs .breadcrumb-item.active { color: #6c757d; max-width: 250px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Melhorias na Navbar - Padronização e Responsividade */ .navbar-nav { flex-wrap: wrap !important; } .navbar-nav .nav-item { display: flex !important; align-items: center; min-width: 110px; justify-content: center; transition: background 0.3s ease; } .navbar-nav .nav-link { white-space: normal !important; line-height: 1.3 !important; text-align: center; padding: 12px 15px !important; height: 100%; width: 100%; display: flex; align-items: center; justify-content: center; font-size: 0.9rem !important; } .navbar-nav .nav-item:hover { background: rgba(255,255,255,0.05); }
/* Melhorias no Dropdown Menu */ .dropdown-menu { background-color: #ffffff !important; border-radius: 12px !important; box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2) !important; border: 1px solid rgba(0,0,0,0.1) !important; padding: 10px 0 !important; margin-top: 5px !important; overflow: visible !important; z-index: 10000 !important; } .dropdown-item { white-space: normal !important; padding: 12px 20px !important; font-size: 0.85rem !important; transition: all 0.2s ease; border-left: 4px solid transparent !important; } .dropdown-item:hover { padding-left: 25px !important; border-left-color: var(--main-color) !important; background: rgba(0,0,0,0.03) !important; } [data-theme='dark'] .dropdown-menu { background: #222 !important; border-color: #444 !important; } [data-theme='dark'] .dropdown-item:hover { background: rgba(255,255,255,0.05) !important; }
/* Sistema de Modais Universal @CanalQb */ .qb-modal-overlay { display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(0, 0, 0, 0.7); backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); z-index: 999999; justify-content: center; align-items: center; padding: 20px; }
.qb-modal-container { background: var(--body-bg, #fff); border-radius: 16px; width: 100%; max-width: 550px; overflow: hidden; box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4); animation: qbModalPopup 0.3s cubic-bezier(0.34, 1.56, 0.64, 1); }
.qb-modal-header { background: linear-gradient(135deg, var(--main-color, #007bff) 0%, #0056b3 100%); padding: 18px 25px; color: #fff; display: flex; align-items: center; justify-content: space-between; }
.qb-modal-header h2 { font-size: 1.25rem; margin: 0; color: #fff !important; font-weight: 600; }
.qb-modal-body { padding: 25px; color: var(--text-color, #333); font-family: inherit; line-height: 1.6; }
.qb-modal-footer { padding: 15px 25px; background: #f8f9fa; border-top: 1px solid #eee; display: flex; justify-content: flex-end; gap: 10px; }
/* Animações */ @keyframes qbModalPopup { from { opacity: 0; transform: scale(0.9) translateY(20px); } to { opacity: 1; transform: scale(1) translateY(0); } }
[data-theme='dark'] .qb-modal-container { background: #1a1a1a; color: #eee; } [data-theme='dark'] .qb-modal-footer { background: #252525; border-color: #333; } [data-theme='dark'] .qb-modal-body { color: #ccc; } /* @CanalQb - Fix Final de Visibilidade Mobile - Off-Canvas Sidebar (LEFT) */ @media (max-width: 991.98px) { .navbar { position: relative; z-index: 10000 !important; } /* Off-canvas sidebar - LEFT side */ .navbar-collapse { background-color: var(--dropdown-menu-bg, #ffffff) !important; position: fixed !important; top: 0 !important; left: -280px !important; width: 280px !important; max-width: 85vw !important; height: 100vh !important; z-index: 10001 !important; padding: 70px 12px 16px !important; box-shadow: 15px 0 50px rgba(0,0,0,0.4) !important; border-right: 1px solid var(--dropdown-divider-color, #eee) !important; overflow-y: auto !important; transform: translateX(0) !important; transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) !important; display: block !important; visibility: visible !important; } .navbar-collapse.show { transform: translateX(100%) !important; } /* Overlay backdrop */ .navbar-overlay { position: fixed !important; top: 0 !important; left: 0 !important; width: 100vw !important; height: 100vh !important; background: rgba(0,0,0,0.5) !important; z-index: 10000 !important; opacity: 0 !important; visibility: hidden !important; transition: opacity 0.3s ease, visibility 0.3s ease !important; } .navbar-overlay.show { opacity: 1 !important; visibility: visible !important; } /* Main nav links - 30% smaller, tighter spacing */ .navbar-nav .nav-link { color: var(--text-color, #000000) !important; font-weight: 600 !important; font-size: 0.85rem !important; padding: 10px 0 !important; border-bottom: 1px solid var(--dropdown-divider-color, #f0f0f0) !important; text-align: left !important; line-height: 1.3 !important; } .navbar-nav .nav-item { margin: 0 !important; } /* Submenu (dropdown) inline inside sidebar - compact */ .navbar-nav .dropdown-menu { position: static !important; float: none !important; width: 100% !important; box-shadow: none !important; border: none !important; background: rgba(0,0,0,0.02) !important; margin: 0 !important; padding: 4px 0 4px 16px !important; display: none; /* Mini scrollbar when >5 items */ max-height: 220px !important; overflow-y: auto !important; } .navbar-nav .dropdown-menu::-webkit-scrollbar { width: 4px !important; } .navbar-nav .dropdown-menu::-webkit-scrollbar-track { background: transparent !important; } .navbar-nav .dropdown-menu::-webkit-scrollbar-thumb { background: var(--main-color, #b5838d) !important; border-radius: 2px !important; } .navbar-nav .dropdown-menu::-webkit-scrollbar-thumb:hover { background: var(--main-color-hover, #a06d77) !important; } .navbar-nav .dropdown.show .dropdown-menu { display: block !important; } .navbar-nav .dropdown-item { padding: 8px 12px !important; color: var(--text-color, #333) !important; border: none !important; font-size: 0.8rem !important; line-height: 1.3 !important; } .navbar-nav .dropdown-item:hover, .navbar-nav .dropdown-item:focus { background: rgba(0,0,0,0.05) !important; color: var(--main-color, #b5838d) !important; } /* Dropdown toggle arrow alignment */ .navbar-nav .nav-item.dropdown > .nav-link::after { float: right !important; margin-top: 2px !important; font-size: 0.7rem !important; } /* Dark mode adjustments for off-canvas */ [data-theme='dark'] .navbar-collapse { background-color: var(--dropdown-menu-bg, #1a1a1a) !important; border-right-color: var(--dropdown-divider-color, #333) !important; box-shadow: 15px 0 50px rgba(0,0,0,0.6) !important; } [data-theme='dark'] .navbar-nav .nav-link { color: var(--text-color, #eee) !important; border-bottom-color: var(--dropdown-divider-color, #333) !important; } [data-theme='dark'] .navbar-nav .dropdown-menu { background: rgba(255,255,255,0.04) !important; } [data-theme='dark'] .navbar-nav .dropdown-item { color: var(--text-color, #ddd) !important; } [data-theme='dark'] .navbar-nav .dropdown-item:hover, [data-theme='dark'] .navbar-nav .dropdown-item:focus { background: rgba(255,255,255,0.08) !important; color: var(--main-color, #e8a8b0) !important; } [data-theme='dark'] .navbar-nav .dropdown-menu::-webkit-scrollbar-thumb { background: var(--main-color, #e8a8b0) !important; } }
/* ===== Skip Links (ícones FA fixos na lateral) ===== */ .skip-link { position: fixed; right: 0; top: 45%; z-index: 9999998; width: 34px; height: 34px; border-radius: 8px 0 0 8px; background: rgba(181,131,141,0.88); color: #fff !important; display: -webkit-box !important; display: -ms-flexbox !important; display: flex !important; -webkit-box-align: center; -ms-flex-align: center; align-items: center; -webkit-box-pack: center; -ms-flex-pack: center; justify-content: center; font-size: 15px; text-decoration: none !important; -webkit-box-shadow: -2px 2px 10px rgba(0,0,0,0.22); box-shadow: -2px 2px 10px rgba(0,0,0,0.22); -webkit-transition: width .2s ease, background .2s ease; transition: width .2s ease, background .2s ease; border: 1px solid rgba(255,255,255,0.2); border-right: none; } .skip-link--footer { top: calc(45% + 42px); } .skip-link:hover { width: 44px; background: rgba(109,104,117,0.95) !important; color: #fff !important; text-decoration: none !important; } .skip-link i { pointer-events: none; } [data-theme='dark'] .skip-link { background: rgba(60,60,80,0.9); } [data-theme='dark'] .skip-link:hover { background: rgba(229,152,155,0.9) !important; }
/* ===== Search box (aberta via .open) ===== */ #nav__search-box.open { display: block !important; z-index: 10001 !important; } @media (min-width: 992px) { .nav__search { position: relative; } #nav__search-box.open { position: absolute; top: 100%; right: 0; min-width: 300px; } } @media (max-width: 991.98px) { .nav__search { position: static; } #nav__search-box.open { position: fixed; top: 56px; left: 0; right: 0; width: 100%; padding: 12px 16px 16px; background: #fff; border-top: 2px solid rgba(181,131,141,0.5); box-shadow: 0 8px 30px rgba(0,0,0,0.22); border-radius: 0 0 12px 12px; } #nav__search-box.open .search-form { display: -webkit-box; display: -ms-flexbox; display: flex; width: 100%; gap: 8px; } #nav__search-box.open .search-input { -webkit-box-flex: 1; -ms-flex: 1; flex: 1; font-size: 16px !important; padding: 10px 14px !important; border-radius: 8px !important; border: 1px solid #ddd !important; } #nav__search-box.open .btn-search { padding: 10px 16px !important; border-radius: 8px !important; background: rgba(181,131,141,0.88) !important; color: #fff !important; border: none !important; } [data-theme='dark'] #nav__search-box.open { background: #1a1a1a; border-top-color: rgba(229,152,155,0.5); } [data-theme='dark'] #nav__search-box.open .search-input { background: #222 !important; color: #eee !important; border-color: #444 !important; } } /* ================================================================= CQB — Estilo para ícones de seta (substituição de ▸ / ▶) ================================================================= */ .cqb-icon-arrow { font-style: normal; font-size: 0.8em; margin: 0 4px; vertical-align: middle; }
/* ================================================================= CQB — Suprime auto ads do AdSense em áreas críticas do layout (anúncios injetados automaticamente dentro do link do título quebram o layout e violam as políticas do AdSense) ================================================================= */ .fbt-post-caption .google-auto-placed, .post-title .google-auto-placed, .post-meta .google-auto-placed, .post-excerpt .google-auto-placed, .index-post-tag .google-auto-placed, .fbt-index-post .google-auto-placed, .bp-content .google-auto-placed, .thumbnail-container .google-auto-placed, .caption-container .google-auto-placed, .fbt-title-caption .google-auto-placed, .elastic-title .google-auto-placed, .is-content .google-auto-placed, .entry-title .google-auto-placed, .fbt-post-title .google-auto-placed, h1 .google-auto-placed, h2 .google-auto-placed, h3 .google-auto-placed, h4 .google-auto-placed, h5 .google-auto-placed, h6 .google-auto-placed { display: none !important; height: 0 !important; min-height: 0 !important; overflow: hidden !important; }

