body.script:
//
(function patchTheme() {
  if (typeof jQuery !== 'undefined') {
    $(function() {
      "use strict";

      // 1. Navegação Premium (Estilo Balão/Bubble)
      $("#LinkList1").each(function() {
        var $container = $(this), $items = $container.find("li"), html = "<ul class='navbar-nav ms-auto clearfix'>", current = false;
        $items.each(function() {
          var t = $(this).text().trim(), h = $(this).find("a").attr("href") || "#";
          if (t.startsWith("_")) {
            if (current) html += '<li><a class="dropdown-item" href="' + h + '">' + t.replace(/^_+/, "").trim() + "</a></li>";
          } else {
            if (current) html += "</ul></li>";
            html += '<li class="nav-item dropdown"><a class="nav-link dropdown-toggle" href="' + h + '" data-bs-toggle="dropdown">' + t + '</a><ul class="dropdown-menu">';
            current = true;
          }
        });
        if (current) html += "</ul></li>";
        $container.html(html + "</ul>");

        // Limpeza de menus vazios
        $container.find("ul.dropdown-menu").each(function() {
          if ($(this).children().length === 0) {
            $(this).closest('li').removeClass('dropdown').find('> .nav-link').removeClass('dropdown-toggle').removeAttr('data-bs-toggle');
            $(this).remove();
          }
        });
      });

      // 2. CSS do Menu (Hover e Balão)
      if (!$('#cqb-fix').length) {
        $('head').append('<style id="cqb-fix">\
          /* Dropdown Menu */\
          .navbar-nav .nav-link::after { display: none !important; }\
          .navbar-nav .nav-item.dropdown > .nav-link::after { display: inline-block !important; margin-left: .4em; vertical-align: .15em; content: ""; border-top: .35em solid; border-right: .3em solid transparent; border-bottom: 0; border-left: .3em solid transparent; opacity: 0.7; }\
          @media (max-width: 991.98px) { .navbar-nav .nav-item.dropdown > .nav-link::after { float: right; margin-top: .55em; } }\
          #LinkList1 .dropdown-menu li { display: block !important; }\
          @media (min-width: 992px) { .dropdown:hover > .dropdown-menu { display: block !important; opacity: 1; visibility: visible; margin-top: 0; } }\
          .dropdown-menu { border: 1px solid rgba(0,0,0,0.1) !important; box-shadow: 0 10px 30px rgba(0,0,0,0.15) !important; border-radius: 12px !important; padding: 10px 0 !important; background: #fff !important; min-width: 200px !important; z-index: 10000 !important; overflow: visible !important; }\
          .dropdown-item { color: #333 !important; padding: 10px 20px !important; font-size: 14px !important; font-weight: 500 !important; display: block !important; white-space: normal !important; }\
          .dropdown-item:hover { background: #f8f9fa !important; color: #000 !important; padding-left: 24px !important; }\
          .dropdown-menu::before { content: ""; position: absolute; top: -6px; left: 20px; border-left: 6px solid transparent; border-right: 6px solid transparent; border-bottom: 6px solid #fff; }\
                          .dropdown-menu.show { display: block !important; } }\
          /* Estilização Hero (Theme Aware) */\
          .hero { background: rgba(0,0,0,0.035) !important; color: #222 !important; padding: 30px; border-radius: 16px; margin: 20px 0; border: 1px solid rgba(0,0,0,0.05); transition: background 0.3s ease, color 0.3s ease; }\
          [data-theme=\'dark\'] .hero { background: rgba(255,255,255,0.06) !important; color: #eee !important; border-color: rgba(255,255,255,0.1); }\
        </style>');
      }

      // 3. Modo Noturno
      $('#dark-mode-switcher').on('click', function() {
        let r = document.documentElement, t = r.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
        r.setAttribute('data-theme', t); localStorage.setItem('theme', t);
      });

      // 4. Sticky Nav, Busca e Topo
      $(window).scroll(function() {
        if ($(window).scrollTop() > 300) $(".fbt_sticky_nav").addClass("sticky__nav scrolling_nav");
        else $(".fbt_sticky_nav").removeClass("sticky__nav scrolling_nav");
      });
      $(".search-trigger").on('click', function(e) {
        e.stopPropagation();
        var $box = $('#nav__search-box');
        $box.toggleClass('open');
        if ($box.hasClass('open')) { $box.find('.search-input').focus(); }
      });
      $(document).on('click', function(e) {
        if (!$(e.target).closest('.nav__search, #nav__search-box').length) {
          $('#nav__search-box').removeClass('open');
        }
      });
      $('#BackToTop').on('click', function(e) { e.preventDefault(); $('html, body').animate({scrollTop:0}, 1200); });

      // 5. Plugins Necessários (Easing)
      jQuery.easing = jQuery.easing || {};
      if(!jQuery.easing.swing){jQuery.easing.swing=function(p){return 0.5-Math.cos(p*Math.PI)/2;}}

      // 6. Load More Posts (AJAX + Auto-scroll)
      (function() {
        var $pager      = $('#blog-pager');
        var $loadWrap   = $('.load-more-posts');
        var $loadBtn    = $('.load-more');
        var $spinner    = $('.load-more > #load-icon');
        var $moreText   = $('span.show-more-items');
        var olderPosts  = $('a.blog-pager-older-link').attr('href');

        // Forçar 10 posts por vez
        function fixUrl(url) {
          if (!url) return url;
          if (url.indexOf('max-results=') > -1) {
            return url.replace(/max-results=\d+/, 'max-results=10');
          } else {
            return url + (url.indexOf('?') > -1 ? '&' : '?') + 'max-results=10';
          }
        }
        olderPosts = fixUrl(olderPosts);

        $pager.hide();
        $loadWrap.show();
        $loadBtn.show();

        var loading = false;

        function carregarMais() {
          if (loading || !olderPosts) return;
          loading = true;
          $spinner.show();
          $moreText.hide();

          $.ajax({
            url: olderPosts,
            success: function(res) {
              var $novos = $(res).find('.blog-posts');
              $novos.children('.status-msg-wrap').remove();
              $('.blog-posts').append($novos.html());

              var next = $(res).find('a.blog-pager-older-link').attr('href');
              olderPosts = fixUrl(next);

              // Remover duplicatas
              var vistos = {};
              $('.fbt-index-post').each(function() {
                var url = $(this).find('a').attr('href');
                if (vistos[url]) { $(this).remove(); }
                else { vistos[url] = true; }
              });

              if (olderPosts) {
                $moreText.text(typeof loadmore_txt !== 'undefined' ? loadmore_txt : 'Carregar mais postagens');
              } else {
                $loadBtn.hide();
                $loadWrap.hide();
              }
            },
            complete: function() {
              $spinner.hide();
              $moreText.show();
              loading = false;
              // Re-verificar se o botão ainda está visível para carregamento sequencial
              if (botaoVisivelNaTela()) { carregarMais(); }
            }
          });
        }

        // Clique manual
        $loadBtn.on('click', function(e) { e.preventDefault(); carregarMais(); });

        // Auto-load Sensível (IntersectionObserver com 600px de margem para antecipação)
        if ('IntersectionObserver' in window) {
          var observer = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
              if (entry.isIntersecting && olderPosts) { carregarMais(); }
            });
          }, { rootMargin: '600px' });
          if ($loadWrap.length) { observer.observe($loadWrap[0]); }
        }

        // Plano B: Auto-load Agressivo (Scroll + Idle)
        var idleTimer = null;
        function botaoVisivelNaTela() {
          if (!$loadWrap.length || !olderPosts || loading) return false;
          var rect = $loadWrap[0].getBoundingClientRect();
          // Aciona se o botão estiver a até 800px de entrar na tela (altíssima sensibilidade)
          return rect.top < (window.innerHeight + 800);
        }
        function iniciarIdleTimer() {
          clearTimeout(idleTimer);
          if (botaoVisivelNaTela()) { carregarMais(); }
          idleTimer = setTimeout(function() {
            if (botaoVisivelNaTela()) { carregarMais(); }
          }, 1000); // Plano B aciona em 1s de ociosidade se visível
        }
        $(window).on('scroll.loadmore touchmove.loadmore', iniciarIdleTimer);
        iniciarIdleTimer(); 
      })();
      // 7. Reading Progress Bar
      $(window).on('scroll', function() {
        var s = $(window).scrollTop(),
            d = $(document).height(),
            c = $(window).height();
        var scrollPercent = (s / (d - c)) * 100;
        $('#reading-progress-bar').css('width', scrollPercent + '%');
      });

      // 8. Global Copy Button Logic
      $(document).on('click', '.post_copy_btn', function() {
        var $btn = $(this);
        var $code = $btn.siblings('code, pre');
        if (!$code.length) $code = $btn.parent().find('code, pre');
        var text = $code.text();

        navigator.clipboard.writeText(text).then(function() {
          var original = $btn.html();
          $btn.text('Copiado!').css('background', '#28a745');
          setTimeout(function() { $btn.html(original).css('background', ''); }, 2000);
        });
      });
    });
  } else { setTimeout(patchTheme, 50); }
})();
