(function(){'use strict';
  var dash = document.getElementById('widgSeoDashboard');
  if(!dash) return;
  var params = new URLSearchParams(window.location.search);
  if(params.get('seo') !== 'true') return;
  dash.classList.add('widg_visible');

  window.widgSeoRefresh = function(){
    var c = document.getElementById('widgSeoContent');
    if(!c) return;
    c.innerHTML = '<p style="color:#999">Atualizando...</p>';
    fetch('http://localhost:3456/refresh',{method:'POST'}).then(function(r){return r.json()}).then(function(j){
      if(j.status==='ok') loadData();
      else c.innerHTML = '<div class="widg_seo_error">Erro: '+(j.error||'desconhecido')+'</div>';
    })['catch'](function(e){c.innerHTML='<div class="widg_seo_error">Servidor offline. Inicie com: node scripts/seo_server.js</div>'});
  };

  function loadData(){
    var c = document.getElementById('widgSeoContent');
    if(!c) return;
    fetch('http://localhost:3456/data').then(function(r){return r.json()}).then(function(d){
      var g=d.ga4||{},s=d.sc||{},ov=g.overview||{},sv=s.overview||{};
      c.innerHTML = 
        '<div class="widg_seo_grid">'+
          '<div class="widg_seo_kpi"><div class="num">'+(ov.activeUsers||0)+'</div><div class="label">Usuarios Ativos (30d)</div></div>'+
          '<div class="widg_seo_kpi"><div class="num">'+(ov.sessions||0)+'</div><div class="label">Sessoes</div></div>'+
          '<div class="widg_seo_kpi"><div class="num">'+(ov.pageViews||0)+'</div><div class="label">Page Views</div></div>'+
          '<div class="widg_seo_kpi"><div class="num">'+(sv.clicks||0)+'</div><div class="label">Cliques SC (30d)</div></div>'+
          '<div class="widg_seo_kpi"><div class="num">'+(sv.impressions||0)+'</div><div class="label">Impressoes SC</div></div>'+
          '<div class="widg_seo_kpi"><div class="num">'+(sv.avgPosition||'-')+'</div><div class="label">Posicao Media</div></div>'+
        '</div>'+
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'+
          '<div><h2 style="font-size:1em;margin-bottom:8px">Top Paginas (GA4)</h2>'+
            '<table class="widg_seo_table"><tr><th>Pagina</th><th>Views</th></tr>'+
            (g.topPages||[]).slice(0,6).map(function(p){return '<tr><td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+p.page+'</td><td>'+p.views+'</td></tr>'}).join('')+
            '</table></div>'+
          '<div><h2 style="font-size:1em;margin-bottom:8px">Top Paginas (SC)</h2>'+
            '<table class="widg_seo_table"><tr><th>Pagina</th><th>Cliques</th></tr>'+
            (s.topPages||[]).slice(0,6).map(function(p){return '<tr><td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+p.page.replace('https://www.canalqb.com.br','')+'</td><td>'+p.clicks+'</td></tr>'}).join('')+
            '</table></div>'+
        '</div>'+
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'+
          '<div><h2 style="font-size:1em;margin-bottom:8px">Fontes de Trafego</h2>'+
            '<table class="widg_seo_table"><tr><th>Fonte</th><th>Sessoes</th></tr>'+
            (g.sources||[]).slice(0,5).map(function(s){return '<tr><td>'+s.source+'</td><td>'+s.sessions+'</td></tr>'}).join('')+
            '</table></div>'+
          '<div><h2 style="font-size:1em;margin-bottom:8px">Tendencia Diaria</h2>'+
            '<table class="widg_seo_table"><tr><th>Data</th><th>Users</th><th>Views</th></tr>'+
            (g.dailyTrend||[]).slice(0,7).map(function(d){return '<tr><td>'+d.date.substring(6,8)+'/'+d.date.substring(4,6)+'</td><td>'+d.users+'</td><td>'+d.views+'</td></tr>'}).join('')+
            '</table></div>'+
        '</div>';
    })['catch'](function(e){
      c.innerHTML = '<div class="widg_seo_error">Servidor offline. Inicie com: node scripts/seo_server.js</div>';
    });
  }

  loadData();
})();
