(function() {
  var navbar = document.getElementById('navbar');
  var overlay = document.querySelector('.navbar-overlay');
  if (!navbar || !overlay) return;

  // Sync overlay with navbar-collapse show/hide
  var observer = new MutationObserver(function(mutations) {
    mutations.forEach(function(mutation) {
      if (mutation.attributeName === 'class') {
        overlay.classList.toggle('show', navbar.classList.contains('show'));
      }
    });
  });
  observer.observe(navbar, { attributes: true, attributeFilter: ['class'] });

  // Close on overlay click
  overlay.addEventListener('click', function() {
    var toggler = document.querySelector('[data-bs-target="#navbar"]');
    if (toggler && navbar.classList.contains('show')) {
      toggler.click();
    }
  });

  // Close on ESC key
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && navbar.classList.contains('show')) {
      var toggler = document.querySelector('[data-bs-target="#navbar"]');
      if (toggler) toggler.click();
    }
  });
})();
//
